"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["92470"],{67347(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modelo_formulario.conflito_de_concorrencia","status":409,"titulo":"Modelo de formul\xe1rio alterado concorrentemente"},"descricao":{"codigo":"uniplus.configuracao.modelo_formulario.conflito_de_concorrencia","requisitos":[],"oQueAconteceu":["Duas escritas sobre o mesmo modelo de formul\xe1rio aconteceram ao mesmo tempo, e esta chegou depois: outra edi\xe7\xe3o, ativa\xe7\xe3o ou desativa\xe7\xe3o j\xe1 tinha sido confirmada entre a leitura do modelo e a grava\xe7\xe3o desta opera\xe7\xe3o. Atinge a atualiza\xe7\xe3o (`PUT /api/configuracao/admin/modelos-formulario/{id}`), a ativa\xe7\xe3o (`POST .../{id}/ativacao`) e a desativa\xe7\xe3o (`DELETE .../{id}`). Nada \xe9 gravado pela opera\xe7\xe3o recusada. A cria\xe7\xe3o n\xe3o responde com este c\xf3digo: o conflito dela \xe9 o de [c\xf3digo do modelo j\xe1 existente](/erros/uniplus.configuracao.modelo_formulario.codigo_ja_existe).","A recusa descreve uma corrida que j\xe1 passou, n\xe3o um estado que permanece: a resposta traz `retryable: true`, e repetir o pedido pode dar certo. Ela vem por \xfaltimo: com um `{id}` que n\xe3o existe prevalece [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado), e, na atualiza\xe7\xe3o, as valida\xe7\xf5es de dom\xednio do conte\xfado, que v\xeam depois da busca e antes da grava\xe7\xe3o, prevalecem com a recusa correspondente. A leitura do corpo, que recusa com 400 o campo n\xe3o anul\xe1vel ausente ou nulo, vem antes de tudo."],"comoResolver":["Repita o pedido. Se a recusa se repetir, consulte o modelo (`GET /api/configuracao/admin/modelos-formulario/{id}`) para ver o que a outra opera\xe7\xe3o gravou e refa\xe7a o pedido sobre o estado atual. Na ativa\xe7\xe3o e na desativa\xe7\xe3o, se a outra opera\xe7\xe3o j\xe1 fez a mesma mudan\xe7a, a repeti\xe7\xe3o responde [modelo j\xe1 ativo](/erros/uniplus.configuracao.modelo_formulario.ja_ativo) ou [modelo j\xe1 desativado](/erros/uniplus.configuracao.modelo_formulario.ja_desativado), e nenhuma provid\xeancia \xe9 necess\xe1ria."],"ondeAparece":["Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Ativa\xe7\xe3o de um modelo de formul\xe1rio","Desativa\xe7\xe3o de um modelo de formul\xe1rio"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modelo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3bbcc2307827ee8c6dab135295710bb856847f61"}}')}}]);